"""Essaint / Off Duty — the source of the second art direction."""
import pathlib,json,re,shutil
R=pathlib.Path(__file__).resolve().parents[1]
def write(path,s): (R/path).write_text(s,encoding='utf-8')
def section(name,body,settings=[],extra={}):write('theme/sections/'+name+'.liquid',body+'\n{% schema %}'+json.dumps({'name':name.replace('-',' ').title(),'settings':settings,'presets':[{'name':name.replace('-',' ').title()}],**extra})+'{% endschema %}')
section('header','''<div class="announcement"><span>CRAFTED IN LEBANON</span><span>COMPLIMENTARY SHIPPING ON ORDERS OVER $100</span><span>7-DAY EASY EXCHANGES</span></div><header class="header"><nav aria-label="Main navigation"><a href="{{ routes.all_products_collection_url }}">SHOP ALL</a><a href="{{ routes.root_url }}#bundles">BUNDLES <span class="nav-dot"></span></a><a href="{{ routes.root_url }}#story">OUR WORLD</a></nav><a class="wordmark" href="{{ routes.root_url }}" aria-label="Essaint home">ESSAINT<span>®</span></a><div class="header-actions"><span class="locale-label">LEBANON / {{ cart.currency.iso_code }}</span><button data-search aria-label="Search products">{% render 'icon', name: 'search' %}</button><button data-cart aria-label="Open shopping bag"><span class="bag-label">BAG</span> [<span data-count>{{ cart.item_count }}</span>]</button><button class="mobile-menu" data-menu aria-label="Open menu" aria-expanded="false"><span></span><span></span></button></div></header>''')
section('hero','''<section class="hero"><div class="hero-image">{% if section.settings.image != blank %}{{ section.settings.image | image_url: width: 2400 | image_tag: fetchpriority: 'high', widths: '800,1200,1800,2400', sizes: '100vw' }}{% else %}<img src="{{ 'campaign-off-duty.png' | asset_url }}" width="1642" height="958" alt="Essaint white tee and striped trousers in a Mediterranean architectural setting" fetchpriority="high">{% endif %}</div><div class="hero-topline"><span>THE EVERYDAY COLLECTION</span><span>BEIRUT, LEBANON — EST. ESSAINT</span></div><div class="hero-copy"><p class="eyebrow"><span class="mini-line"></span> ESSENTIALS, WITH ATTITUDE.</p><h1>{{ section.settings.heading }}<em>{{ section.settings.subheading }}</em></h1><p class="hero-description">Easy silhouettes. A different kind of presence.</p><div class="hero-ctas"><a class="button button-light" href="{{ routes.all_products_collection_url }}">SHOP THE COLLECTION <span>↗</span></a><a class="hero-secondary" href="{{ routes.root_url }}#bundles">BUILD YOUR FIT <span>↗</span></a></div></div><div class="hero-foot"><span>LESS NOISE. MORE YOU.</span><a href="{{ routes.root_url }}#essentials">EXPLORE ↓</a><span>CAMPAIGN / 01</span></div></section><div class="category-rail"><a href="{{ routes.all_products_collection_url }}?filter.p.product_type=T-Shirts" data-category-link="tees"><span>01</span> THE TEES <b>↗</b></a><a href="{{ routes.all_products_collection_url }}" data-category-link="bottoms"><span>02</span> THE TROUSERS <b>↗</b></a><a href="{{ routes.root_url }}#bundles"><span>03</span> THE FULL FIT <b>↗</b></a></div>''',[{'type':'text','id':'heading','label':'Main headline','default':'OFF DUTY.'},{'type':'text','id':'subheading','label':'Italic headline','default':'On purpose.'},{'type':'image_picker','id':'image','label':'Campaign image'}])
section('essentials','''<section class="section essentials" id="essentials"><div class="section-heading"><div><p class="eyebrow">/ THE ESSAINT ROTATION</p><h2>GOOD ON REPEAT.</h2></div><a class="text-link" href="{{ routes.all_products_collection_url }}">SHOP ALL PIECES ↗</a></div><div class="essentials-toolbar"><div class="filter-chips"><button class="active" data-edit-filter="all" aria-pressed="true">THE EDIT</button><button data-edit-filter="tees" aria-pressed="false">TEES</button><button data-edit-filter="bottoms" aria-pressed="false">TROUSERS</button></div><span class="micro">CONSIDERED CUTS. EVERYDAY PRICES.</span></div><div class="product-grid" data-edit-grid>{% assign featured = section.settings.collection | default: collections.all %}{% for product in featured.products limit: 24 %}{% render 'product-card', product: product %}{% endfor %}</div><noscript><p>Explore every piece in the collection above.</p></noscript></section>''',[{'type':'collection','id':'collection','label':'Featured collection'}])
write('theme/snippets/product-card.liquid','''{% assign title_lower = product.title | downcase %}<article class="product-card" data-kind="{% if title_lower contains 't-shirt' %}tees{% else %}bottoms{% endif %}"><div class="product-media"><a class="product-photo" href="{{ product.url }}">{% if product.featured_image %}{{ product.featured_image | image_url: width: 900 | image_tag: loading: 'lazy', widths: '300,500,700,900', sizes: '(min-width: 900px) 25vw, 50vw' }}{% endif %}{% if product.images[1] %}{{ product.images[1] | image_url: width: 900 | image_tag: loading: 'lazy', class: 'alternate' }}{% endif %}<span class="badge">{% unless product.available %}SOLD OUT{% else %}{% if product.compare_at_price > product.price %}PRICE DROP{% endif %}{% endunless %}</span></a><button class="quick-add" data-product="{{ product.handle }}" aria-label="Choose options for {{ product.title | escape }}"><span>QUICK ADD</span><b>+</b></button></div><div class="product-meta"><a href="{{ product.url }}">{{ product.title }}</a><span>{{ product.price | money }}{% if product.compare_at_price > product.price %} <s>{{ product.compare_at_price | money }}</s>{% endif %}</span></div><p class="product-options">{{ product.options_with_values.first.values | join: ' / ' }}</p></article>''')
section('bundles','''<section class="bundle-section" id="bundles"><div class="bundle-intro"><p class="eyebrow">/ THE OUTFIT STUDIO</p><h2>YOUR FIT. <em>Your rules.</em></h2><p>One top. One bottom. Endless ways to make it yours.</p></div><div class="studio" data-studio><div class="studio-visual"><div class="studio-stamp">ESSAINT<br><span>THE ART OF EVERYDAY.</span></div><div class="studio-images"><div><img data-studio-image="top" src="{{ 'over-size-t-shirt-0.jpg' | asset_url }}" width="566" height="512" alt="Oversized T-Shirt"><span>01 / THE TOP</span></div><span class="studio-plus">+</span><div><img data-studio-image="bottom" src="{{ 'milano-striped-pants-dropping-next-week-0.png' | asset_url }}" width="1023" height="1276" alt="Milano Striped Pants"><span>02 / THE BOTTOM</span></div></div><div class="studio-caption"><span>TWO PIECES. ONE POINT OF VIEW.</span><span>01 + 02</span></div></div><form class="studio-form"><p class="eyebrow">MAKE IT A SET</p><h3>BUILD YOUR UNIFORM.</h3><div class="studio-step"><div class="step-label"><span>01</span><label for="studio-top-{{ section.id }}">CHOOSE YOUR TOP</label></div><select id="studio-top-{{ section.id }}" data-studio-product="top">{% assign tops = section.settings.tops | default: collections.all %}{% for item in tops.products %}{% assign lower = item.title | downcase %}{% if lower contains 't-shirt' %}<option value="{{ item.handle }}" {% if item.handle == 'over-size-t-shirt' %}selected{% endif %}>{{ item.title }}</option>{% endif %}{% endfor %}</select><label class="variant-label" for="studio-top-variant-{{ section.id }}">SIZE / COLOR</label><select id="studio-top-variant-{{ section.id }}" data-studio-variant="top" disabled><option>Choose a piece to see available options</option></select></div><div class="studio-step"><div class="step-label"><span>02</span><label for="studio-bottom-{{ section.id }}">CHOOSE YOUR BOTTOM</label></div><select id="studio-bottom-{{ section.id }}" data-studio-product="bottom">{% assign bottoms = section.settings.bottoms | default: collections.all %}{% for item in bottoms.products %}{% assign lower = item.title | downcase %}{% unless lower contains 't-shirt' %}<option value="{{ item.handle }}" {% if item.handle == 'milano-striped-pants-dropping-next-week' %}selected{% endif %}>{{ item.title }}</option>{% endunless %}{% endfor %}</select><label class="variant-label" for="studio-bottom-variant-{{ section.id }}">SIZE / COLOR</label><select id="studio-bottom-variant-{{ section.id }}" data-studio-variant="bottom" disabled><option>Choose a piece to see available options</option></select></div><div class="studio-total"><span>YOUR SET TOTAL</span><strong data-studio-total>—</strong></div><button class="button" data-studio-add disabled>ADD THE FULL FIT <span>↗</span></button><p class="studio-note" data-studio-message>Pick your pieces. Select your fit. We'll do the rest.</p><noscript><p>Enable JavaScript to build a set, or shop each product individually.</p></noscript></form></div><div class="preset-row"><span>NEED A STARTING POINT?</span>{% for block in section.blocks %}{% assign top = block.settings.top %}{% assign bottom = block.settings.bottom %}{% if top != blank and bottom != blank %}<button {{ block.shopify_attributes }} data-studio-preset="{{ top.handle }},{{ bottom.handle }}">{{ block.settings.title }} ↗</button>{% endif %}{% endfor %}</div></section>''',[{'type':'collection','id':'tops','label':'Tops collection'},{'type':'collection','id':'bottoms','label':'Bottoms collection'}],{'max_blocks':3,'blocks':[{'type':'outfit','name':'Suggested outfit','settings':[{'type':'text','id':'title','label':'Title','default':'The striped set'},{'type':'product','id':'top','label':'Top'},{'type':'product','id':'bottom','label':'Bottom'}]}]})
section('story','''<section class="story" id="story"><div class="story-heading"><p class="eyebrow">/ ROOTED IN LEBANON</p><h2>NO DRESS CODE.<br><em>Just you.</em></h2><p>For slow mornings. For late plans.<br>For everything that happens in between.</p></div><div class="lookbook-grid"><a class="lookbook-photo lookbook-tall" href="{{ routes.root_url }}#bundles"><img src="{{ 'essaint-campaign-original.jpg' | asset_url }}" alt="Essaint striped trousers worn beside a pool in Lebanon" width="1080" height="1350" loading="lazy"><span>LOOK 01 / OUT OF OFFICE <b>↗</b></span></a><div class="lookbook-right"><a class="lookbook-photo" href="{{ routes.all_products_collection_url }}"><img src="{{ 'tailored-pants-0.jpg' | asset_url }}" width="1000" height="1250" alt="Essaint tailored trousers" loading="lazy"><span>LOOK 02 / AFTER HOURS <b>↗</b></span></a><div class="lookbook-note"><span class="micro">THE ESSAINT POINT OF VIEW</span><p>Nothing to prove.<br><em>Everything to wear.</em></p><a class="text-link" href="{{ routes.all_products_collection_url }}">FIND YOUR EVERYDAY ↗</a></div></div></div></section><div class="service-strip"><span>CRAFTED IN LEBANON</span><span>SHIPPING ON US OVER $100</span><span>7-DAY EASY EXCHANGES</span></div>''')
section('footer','''<footer class="footer"><div class="footer-news"><div><p class="eyebrow">THE INNER CIRCLE</p><h2>STAY IN<br><em>the know.</em></h2></div><div class="newsletter"><p>New pieces. New perspectives.<br>Essaint, before everyone else.</p>{% form 'customer' %}<input type="hidden" name="contact[tags]" value="newsletter"><label class="sr-only" for="NewsletterEmail">Email address</label><div class="email-field"><input id="NewsletterEmail" name="contact[email]" type="email" required placeholder="YOUR EMAIL ADDRESS" autocomplete="email"><button aria-label="Subscribe">↗</button></div>{{ form.errors | default_errors }}{% if form.posted_successfully? %}<p>You're on the list. Welcome to Essaint.</p>{% endif %}{% endform %}</div></div><div class="footer-links"><div><span class="micro">BEIRUT, LEBANON</span><p>Everyday essentials.<br>Independently Essaint.</p></div><div><h3>EXPLORE</h3><a href="{{ routes.all_products_collection_url }}">Shop all</a><a href="{{ routes.root_url }}#bundles">Outfit studio</a><a href="{{ routes.root_url }}#story">Our world</a></div><div><h3>LET'S TALK</h3><a href="/pages/contact">Contact</a><a href="https://wa.me/96171236353" target="_blank" rel="noopener">WhatsApp ↗</a><a href="{{ routes.search_url }}">Search</a></div><div><h3>THE DETAILS</h3>{% for policy in shop.policies %}{% if policy.body != blank %}<a href="{{ policy.url }}">{{ policy.title }}</a>{% endif %}{% endfor %}</div></div><a class="footer-wordmark" href="{{ routes.root_url }}" aria-label="Essaint home">ESSAINT<span>®</span></a><div class="footer-bottom"><span>© {{ 'now' | date: '%Y' }} ESSAINT</span><span>LESS NOISE. MORE YOU.</span><span>LEBANON / {{ cart.currency.iso_code }}</span></div></footer><nav class="mobile-dock" aria-label="Quick navigation"><a href="{{ routes.all_products_collection_url }}">SHOP</a><a href="{{ routes.root_url }}#bundles">BUILD A FIT</a><button data-search>SEARCH</button><button data-cart>BAG [<span data-count>{{ cart.item_count }}</span>]</button></nav>''')
layout=(R/'theme/layout/theme.liquid').read_text(encoding='utf-8')
if "'studio.js'" not in layout:layout=layout.replace('</head>',"<script src=\"{{ 'studio.js' | asset_url }}\" defer></script></head>")
write('theme/layout/theme.liquid',layout)
index=json.loads((R/'theme/templates/index.json').read_text());index['sections']['0']['settings']={'heading':'OFF DUTY.','subheading':'On purpose.'}
for i,title in enumerate(['The striped set','The linen set','The city set']):index['sections']['2']['blocks'][str(i)]['settings']['title']=title
write('theme/templates/index.json',json.dumps(index,indent=2))
shutil.copy(R/'data/essaint-campaign.jpg',R/'theme/assets/essaint-campaign-original.jpg')
print('Applied Off Duty art direction to all storefront sections.')

config=json.loads((R / "theme/config/settings_schema.json").read_text(encoding="utf-8"));config[0]["theme_name"]="Essaint Off Duty";config[0]["theme_version"]="2.0.0";write("theme/config/settings_schema.json",json.dumps(config,indent=2))

import runpy
runpy.run_path(str(R / "scripts/refine.py"))
